import React, { useState, useRef, useEffect } from "react";

export default function Ubicaciones() {
  const chatEndRef = useRef(null);

  const [messages, setMessages] = useState([
    { type: "bot", content: "options", timestamp: new Date() },
  ]);
  const [inputValue, setInputValue] = useState("");
  const [showMoreOptions, setShowMoreOptions] = useState(false);

  const predefinedOptions = [
    { img: "/item-chat.png", text: "Edificio A" },
    { img: "/item-chat.png", text: "Edificio B" },
    { img: "/item-chat.png", text: "Edificio C" },
    { img: "/item-chat.png", text: "Biblioteca" },
    { img: "/item-chat.png", text: "Mas opciones..." },
  ];

  const additionalOptions = [
    { img: "/item-chat.png", text: "Cafetería" },
    { img: "/item-chat.png", text: "Laboratorio" },
    { img: "/item-chat.png", text: "Estacionamiento" },
  ];

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const handleOptionClick = (option) => {
    const userMessage = { type: "user", content: option, timestamp: new Date() };

    const botInfo = {
      type: "bot",
      content: `Para llegar a ${option} sigue las siguientes indicaciones:
1.- Ingresa al campus por la entrada principal.
2.- Dirígete a la sección correspondiente según el mapa.
3.- Sigue las señales indicadas.`,
      timestamp: new Date(),
    };

    const botActions = {
      type: "bot",
      content: 'Si quiere cambiar de ubicación, presione "Cambiar", si quiere salir, presione "Salir".',
      timestamp: new Date(),
      actions: [
        { label: "Cambiar", action: "change" },
        { label: "Salir", action: "exit" },
      ],
    };

    if (option === "Mas opciones...") {
      setShowMoreOptions(true);
      setMessages([
        ...messages,
        userMessage,
        { type: "bot", content: "moreOptions", timestamp: new Date() },
        {
          type: "bot",
          content: "Si no encuentras la ubicación que buscas, escríbela en el chat.",
          timestamp: new Date(),
        },
      ]);
    } else {
      setMessages([...messages, userMessage, botInfo, botActions]);
    }
  };

  const handleSendMessage = () => {
    if (!inputValue.trim()) return;
    const userMessage = { type: "user", content: inputValue, timestamp: new Date() };
    setMessages([...messages, userMessage]);

    // Respuesta automática simulada
    setTimeout(() => {
      const botResponse = {
        type: "bot",
        content: `Has preguntado por "${inputValue}". Te recomiendo consultar el mapa o seleccionar una opción.`,
        timestamp: new Date(),
      };
      setMessages((prev) => [...prev, botResponse]);
    }, 500);

    setInputValue("");
  };

  const handleActionClick = (action) => {
    if (action === "change") {
      setMessages([{ type: "bot", content: "options", timestamp: new Date() }]);
      setShowMoreOptions(false);
    } else if (action === "exit") {
      window.location.href = "/";
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === "Enter") handleSendMessage();
  };

  return (
    <div className="ubicaciones-container">
      <header className="ubicaciones-header">
        <div className="title-logo">
          <h1>Ubicaciones</h1>
          <div className="header-logo">
            <img src="/logo-app.png" alt="Logo" />
          </div>
        </div>
      </header>

      <div className="chat-area">
        {messages.map((message, index) => (
          <div key={index} className={`chat-message ${message.type}`}>
            <div className="avatar">
              <img
                src={message.type === "bot" ? "/logo-app.png" : "/img-user.png"}
                alt={message.type === "bot" ? "Bot" : "User"}
              />
            </div>

            <div className="message-with-actions">
              {message.content === "options" ? (
                <div className="options-box">
                  <h3>Elige una ubicación:</h3>
                  {predefinedOptions.map((option, idx) => (
                    <button key={idx} onClick={() => handleOptionClick(option.text)}>
                      <img src={option.img} alt={option.text} className="option-img" />
                      <span>{option.text}</span>
                    </button>
                  ))}
                </div>
              ) : message.content === "moreOptions" ? (
                <div className="options-box">
                  <h3>Más ubicaciones:</h3>
                  {additionalOptions.map((option, idx) => (
                    <button key={idx} onClick={() => handleOptionClick(option.text)}>
                      <img src={option.img} alt={option.text} className="option-img" />
                      <span>{option.text}</span>
                    </button>
                  ))}
                </div>
              ) : (
                <div className={`message-box ${message.type}`}>
                  <p>{message.content}</p>
                </div>
              )}

              {message.actions && message.actions.length > 0 && (
                <div className="actions-row">
                  {message.actions.map((action, idx) => (
                    <button key={idx} onClick={() => handleActionClick(action.action)} className="action-button">
                      {action.label}
                    </button>
                  ))}
                </div>
              )}
            </div>
          </div>
        ))}
        <div ref={chatEndRef}></div>
      </div>

      <div className="input-area">
        <input
          type="text"
          placeholder="Escribe tu mensaje..."
          value={inputValue}
          onChange={(e) => setInputValue(e.target.value)}
          onKeyPress={handleKeyPress}
        />
        <button onClick={handleSendMessage}>Enviar</button>
      </div>
    </div>
  );
}
